add_filter( 'woocommerce_order_actions', 'perfectpixel_order_action_view_thankyou' );
add_action( 'woocommerce_order_action_perfectpixel_view_thankyou', 'perfectpixel_order_action_view_thankyou_run' );

function perfectpixel_order_action_view_thankyou( $actions ) {
	$actions['perfectpixel_view_thankyou'] = '{{view_thankyou_label}}';
	return $actions;
}

function perfectpixel_order_action_view_thankyou_run( $order ) {
	// The order is saved first; redirect once WooCommerce finishes the request.
	add_filter(
		'redirect_post_location',
		static function () use ( $order ) {
			return $order->get_checkout_order_received_url();
		}
	);
	add_filter(
		'woocommerce_redirect_order_location',
		static function () use ( $order ) {
			return $order->get_checkout_order_received_url();
		}
	);
}
